import { mapString } from './helpers/mapString.mjs';
import { calcAge } from './helpers/calcAge.mjs';
import { generateId } from './helpers/generateId.mjs';

export const createUser = (user) => {
  if (!user) {
    return {
      id: undefined,
      firstName: undefined,
      lastName: undefined,
      dateBirth: undefined,
      age: undefined,
      purpose: undefined
  }
}
  const { name, dateBirth, purpose } = user;
  let [firstName, lastName] = !!name ? name.split(' ') : [];
  return {
    id: generateId(),
    firstName: mapString(firstName),
    lastName: mapString(lastName),
    dateBirth,
    age: calcAge(dateBirth),
    purpose: mapString(purpose)
  };
};